'use client';

import { useState, useEffect } from 'react';
import axios from 'axios';
import Link from 'next/link';
import { IconButton } from '@mui/material';
import { Add as AddIcon, Edit as EditIcon, Delete as DeleteIcon, Search as SearchIcon } from '@mui/icons-material';
import Sidebar from "../../components/sidebar";
import Navbar from "../../components/Navbar";

export default function ListTuteur() {
  const [tuteurs, setTuteurs] = useState([]);
  const [file, setFile] = useState(null);
  const [message, setMessage] = useState("");
  const [dragging, setDragging] = useState(false);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");

  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(5);

  useEffect(() => {
    getTuteurs();
  }, []);

  const getTuteurs = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/tuteurs');
      setTuteurs(response.data);
    } catch (err) {
      console.error("Erreur lors de la récupération des tuteurs :", err);
    }
  };

  const deleteTuteur = async (id) => {
    if (!window.confirm("Voulez-vous vraiment supprimer ce tuteur ?")) return;

    try {
      await axios.delete(`http://localhost:5000/api/deletetuteur/${id}`);
      getTuteurs();
    } catch (err) {
      console.error("Erreur lors de la suppression du tuteur :", err);
    }
  };

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setDragging(true);
  };

  const handleDragLeave = () => {
    setDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      setFile(e.dataTransfer.files[0]);
    }
  };

  const handleUpload = async () => {
    if (!file) {
      setMessage("Veuillez choisir un fichier.");
      return;
    }
    setLoading(true);
    setMessage("");

    const formData = new FormData();
    formData.append("file", file);

    try {
      const response = await axios.post("http://localhost:5000/api/import-tuteurs", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      if (response.data?.message) {
        setMessage(response.data.message);
      } else {
        setMessage("Données extraites et importées avec succès !");
        getTuteurs();
      }
    } catch (error) {
      console.error("Erreur lors de l'importation :", error);
      setMessage(error instanceof Error ? `Erreur lors de l'importation : ${error.message}` : "Erreur inconnue lors de l'importation.");
    } finally {
      setLoading(false);
    }
  };

  const filteredTuteurs = tuteurs.filter(tuteur =>
    tuteur.nom.toLowerCase().includes(search.toLowerCase()) || 
    tuteur.prenom.toLowerCase().includes(search.toLowerCase()) ||
    tuteur.email.toLowerCase().includes(search.toLowerCase())
  );

  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentTuteurs = filteredTuteurs.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(filteredTuteurs.length / itemsPerPage);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);
  const handleItemsPerPageChange = (e) => setItemsPerPage(Number(e.target.value));

  return (
    <div className="flex h-screen min-h-screen w-screen bg-gradient-to-r from-blue-50 to-gray-50">
      <Sidebar className="h-screen hidden lg:block" />
      <div className="w-full flex flex-col h-screen">
        <Navbar />
        <div className="w-full flex-1 py-5 px-6 overflow-hidden">
          <div className="flex flex-col sm:flex-row justify-between items-center mb-6">
            <Link href="/users/createTute">
              <button className="bg-gradient-to-r from-blue-500 to-blue-600 text-white p-3 rounded-lg flex items-center justify-center hover:from-blue-600 hover:to-blue-700 transition duration-200 shadow-lg hover:shadow-xl mb-3 sm:mb-0">
                <AddIcon className="mr-2" />
                Ajouter un tuteur
              </button>
            </Link>

            <div className="max-w-full sm:max-w-md p-6 text-right mb-3 border rounded-xl shadow-lg bg-gradient-to-r from-white to-gray-50">
              <h1 className="text-md font-semibold mb-4 text-gray-800">Importer les informations des tuteurs</h1>
              <div
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
                className={`border-2 border-dashed p-6 text-center rounded-lg ${dragging ? 'bg-blue-50' : 'bg-white'} transition-all duration-300`}
              >
                {file ? <p className="text-gray-700">{file.name}</p> : <p className="text-gray-500">Glissez et déposez un fichier ici ou cliquez pour sélectionner</p>}
                <input type="file" accept=".xlsx, .xls" onChange={handleFileChange} className="hidden" id="fileInput" />
                <label htmlFor="fileInput" className="cursor-pointer text-blue-600 hover:text-blue-700">Sélectionner un fichier</label>
              </div>
              <button
                onClick={handleUpload}
                disabled={loading}
                className="mt-4 px-4 py-2 bg-gradient-to-r from-blue-500 to-blue-600 text-white rounded-lg hover:from-blue-600 hover:to-blue-700 transition duration-200 shadow-lg hover:shadow-xl disabled:opacity-50"
              >
                {loading ? "Importation..." : "Importer"}
              </button>
              {message && <p className="mt-3 text-red-600 text-sm">{message}</p>}
            </div>
          </div>

          <h1 className="text-3xl font-semibold mb-6 text-center text-gray-800">Liste des tuteurs</h1>
          <div className="relative w-full sm:w-96 mb-6">
            <input
              type="text"
              placeholder="Rechercher par nom, prénom ou email"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-10 pr-4 py-2 bg-white border border-gray-300 rounded-lg focus:outline-none focus:border-blue-500 w-full shadow-sm"
            />
            <SearchIcon className="absolute left-3 top-2.5 text-gray-400" />
          </div>
          
          <div className="bg-white rounded-xl shadow-lg overflow-hidden">
            <table className="w-full">
              <thead className="bg-gradient-to-r from-blue-500 to-blue-600 sticky top-0">
                <tr>
                  <th className="p-4 text-left text-white">ID</th>
                  <th className="p-4 text-left text-white">Nom</th>
                  <th className="p-4 text-left text-white">Prénom</th>
                  <th className="p-4 text-left text-white">Email</th>
                  <th className="p-4 text-left text-white">Mot de Passe</th>
                  <th className="p-4 text-left text-white">Année</th>
                  <th className="p-4 text-left text-white">Classe</th>
                  <th className="p-4 text-left text-white">Filière</th>
                  <th className="p-4 text-center text-white">Actions</th>
                </tr>
              </thead>
              <tbody>
                {currentTuteurs.map((tuteur, index) => (
                  <tr
                    key={tuteur.idTuteur}
                    className={`border-b border-gray-100 hover:bg-gray-50 transition ${index % 2 === 0 ? 'bg-gray-50' : 'bg-white'}`}
                  >
                    <td className="p-4 text-gray-800">{tuteur.idTuteur}</td>
                    <td className="p-4 text-gray-800">{tuteur.nom}</td>
                    <td className="p-4 text-gray-800">{tuteur.prenom}</td>
                    <td className="p-4 text-gray-600">{tuteur.email}</td>
                    <td className="p-4 text-gray-600">{tuteur.motDePasse}</td>
                    <td className="p-4 text-gray-600">{tuteur.annee}</td>
                    <td className="p-4 text-gray-600">{tuteur.classe}</td>
                    <td className="p-4 text-gray-600">{tuteur.filiere}</td>
                    <td className="p-4 text-center flex justify-center space-x-3">
                      <Link href={`/users/editTute/${tuteur.idTuteur}`}>
                        <button className="text-blue-500 hover:text-blue-700 transition duration-200">
                          <EditIcon />
                        </button>
                      </Link>
                      <button
                        onClick={() => deleteTuteur(tuteur.idTuteur)}
                        className="text-red-500 hover:text-red-700 transition duration-200"
                      >
                        <DeleteIcon />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* Pagination */}
            <div className="flex justify-between items-center p-4 bg-gradient-to-r from-blue-50 to-gray-50">
              <select
                onChange={handleItemsPerPageChange}
                value={itemsPerPage}
                className="border p-2 rounded-lg shadow-sm"
              >
                <option value={5}>5 par page</option>
                <option value={10}>10 par page</option>
                <option value={15}>15 par page</option>
              </select>
              <div className="flex space-x-2">
                {Array.from({ length: totalPages }, (_, index) => (
                  <button
                    key={index}
                    onClick={() => paginate(index + 1)}
                    className={`px-4 py-2 text-sm rounded-lg ${currentPage === index + 1 ? 'bg-blue-600 text-white' : 'bg-white text-blue-600'}`}
                  >
                    {index + 1}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}